// Anthropic provider. Speaks the neutral message format defined in ./index.js.
const API = "https://api.anthropic.com/v1/messages";

function toAnthropicMessages(messages) {
  return messages.map((m) => ({
    role: m.role,
    content: m.content.map((b) => {
      if (b.type === "text") return { type: "text", text: b.text };
      if (b.type === "tool_call")
        return { type: "tool_use", id: b.id, name: b.name, input: b.args };
      if (b.type === "tool_result")
        return {
          type: "tool_result",
          tool_use_id: b.id,
          content: typeof b.content === "string" ? b.content : JSON.stringify(b.content),
        };
      throw new Error(`unknown block type ${b.type}`);
    }),
  }));
}

export function makeAnthropic({ model, apiKey, maxTokens = 2048 }) {
  if (!apiKey) throw new Error("ANTHROPIC_API_KEY not set");
  return {
    name: "anthropic",
    model,
    async chat({ system, messages, tools }) {
      const body = {
        model,
        max_tokens: maxTokens,
        system,
        messages: toAnthropicMessages(messages),
      };
      if (tools?.length) {
        body.tools = tools.map((t) => ({
          name: t.name,
          description: t.description,
          input_schema: t.parameters,
        }));
      }
      const res = await fetch(API, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          "x-api-key": apiKey,
          "anthropic-version": "2023-06-01",
        },
        body: JSON.stringify(body),
      });
      if (!res.ok) throw new Error(`anthropic ${res.status}: ${await res.text()}`);
      const data = await res.json();
      const text = data.content
        .filter((b) => b.type === "text")
        .map((b) => b.text)
        .join("");
      const toolCalls = data.content
        .filter((b) => b.type === "tool_use")
        .map((b) => ({ id: b.id, name: b.name, args: b.input }));
      return { text, toolCalls, stopReason: data.stop_reason, raw: data };
    },
  };
}


