// Gemini provider. Speaks the neutral message format defined in ./index.js.
// Uses the generateContent REST endpoint with function-calling.
const BASE = "https://generativelanguage.googleapis.com/v1beta/models";

// Gemini disallows some JSON Schema keywords; strip to the supported subset.
function cleanSchema(s) {
  if (!s || typeof s !== "object") return s;
  const out = {};
  for (const [k, v] of Object.entries(s)) {
    if (["additionalProperties", "$schema", "default"].includes(k)) continue;
    if (k === "properties") {
      out.properties = Object.fromEntries(
        Object.entries(v).map(([pk, pv]) => [pk, cleanSchema(pv)])
      );
    } else if (k === "items") {
      out.items = cleanSchema(v);
    } else {
      out[k] = v;
    }
  }
  return out;
}

function toContents(messages) {
  // Gemini: role is "user" or "model"; tool results go in a "user" turn as functionResponse.
  const contents = [];
  for (const m of messages) {
    const role = m.role === "assistant" ? "model" : "user";
    const parts = [];
    for (const b of m.content) {
      if (b.type === "text") parts.push({ text: b.text });
      else if (b.type === "tool_call")
        parts.push({ functionCall: { name: b.name, args: b.args || {} } });
      else if (b.type === "tool_result")
        parts.push({
          functionResponse: {
            name: b.name,
            response: {
              result: typeof b.content === "string" ? b.content : JSON.stringify(b.content),
            },
          },
        });
    }
    contents.push({ role, parts });
  }
  return contents;
}

export function makeGemini({ model, apiKey, maxTokens = 2048 }) {
  if (!apiKey) throw new Error("GEMINI_API_KEY not set");
  return {
    name: "gemini",
    model,
    async chat({ system, messages, tools }) {
      const body = {
        contents: toContents(messages),
        generationConfig: { maxOutputTokens: maxTokens },
      };
      if (system) body.systemInstruction = { parts: [{ text: system }] };
      if (tools?.length) {
        body.tools = [
          {
            functionDeclarations: tools.map((t) => ({
              name: t.name,
              description: t.description,
              parameters: cleanSchema(t.parameters),
            })),
          },
        ];
      }
      const url = `${BASE}/${model}:generateContent?key=${apiKey}`;
      const res = await fetch(url, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(body),
      });
      if (!res.ok) throw new Error(`gemini ${res.status}: ${await res.text()}`);
      const data = await res.json();
      const cand = data.candidates?.[0];
      const parts = cand?.content?.parts || [];
      const text = parts.filter((p) => p.text).map((p) => p.text).join("");
      const toolCalls = parts
        .filter((p) => p.functionCall)
        // Gemini doesn't return ids; synthesize one for our neutral format.
        .map((p, i) => ({ id: `${p.functionCall.name}_${i}`, name: p.functionCall.name, args: p.functionCall.args || {} }));
      return { text, toolCalls, stopReason: cand?.finishReason, raw: data };
    },
  };
}


