// Neutral message format used across providers.
//
// message:   { role: "user" | "assistant", content: Block[] }
// Block:
//   { type: "text", text }
//   { type: "tool_call", id, name, args }      (assistant -> tool)
//   { type: "tool_result", id, name, content } (tool -> assistant, content is string)
//
// tool:      { name, description, parameters: <JSON Schema object> }
//
// provider.chat({ system, messages, tools }) ->
//   { text, toolCalls: [{id,name,args}], stopReason, raw }

import { makeAnthropic } from "./anthropic.js";
import { makeGemini } from "./gemini.js";

const DEFAULT_MODELS = {
  anthropic: "claude-sonnet-4-6",
  gemini: "gemini-2.5-pro",
};

export function makeProvider({ provider, model, maxTokens }) {
  model = model || DEFAULT_MODELS[provider];
  if (provider === "anthropic")
    return makeAnthropic({ model, apiKey: process.env.ANTHROPIC_API_KEY, maxTokens });
  if (provider === "gemini")
    return makeGemini({ model, apiKey: process.env.GEMINI_API_KEY || process.env.GOOGLE_API_KEY, maxTokens });
  throw new Error(`unknown provider: ${provider}`);
}


