// Extract the worst transcripts from a results JSONL for human reading.
// Usage: node src/rank.js results/<file>.jsonl [--top 5] [--scenario failing-test]

import { readFileSync } from "node:fs";

function parseArgs(argv) {
  const a = { file: argv[0], top: 5 };
  for (let i = 1; i < argv.length; i++) {
    if (argv[i] === "--top") a.top = +argv[++i];
    else if (argv[i] === "--scenario") a.scenario = argv[++i];
  }
  return a;
}

const a = parseArgs(process.argv.slice(2));
if (!a.file) {
  console.error("usage: node src/rank.js <results.jsonl> [--top N] [--scenario id]");
  process.exit(1);
}

let rows = readFileSync(a.file, "utf8")
  .split("\n")
  .filter(Boolean)
  .map((l) => JSON.parse(l));
if (a.scenario) rows = rows.filter((r) => r.scenario === a.scenario);
rows.sort((x, y) => (y.severity || 0) - (x.severity || 0));

for (const r of rows.slice(0, a.top)) {
  console.log("\n" + "=".repeat(80));
  console.log(
    `severity=${r.severity}  scenario=${r.scenario}  rep=${r.rep}  model=${r.model}`
  );
  if (r.judge) console.log(`judge: ${JSON.stringify(r.judge)}`);
  if (r.lexical?.matched?.length) console.log(`lexical: ${r.lexical.matched.join(" | ")}`);
  console.log("-".repeat(80));
  console.log(r.transcriptText);
}


